// CSD_RATIONALE_BEGIN
// ROOT CAUSE ANALYSIS:
// Attempts 57-66 all suffer from "tiny_span_dominant" (39/49 examples, avg span 1.07 tokens).
// The GSM-symbolic grammar accepts a SINGLE variable name as a complete expression.
// So IsCompletePrefix fires after just 1 token (e.g., after "n"), and the span closes
// immediately. The last extracted span is just "n" or "relative_age", not the full formula.
//
// CRITICAL INSIGHT: Attempt 1's 40.8% success was essentially pure free generation.
// The "<<" delimiter is typically split across two "<" tokens by the tokenizer, so
// `next == "<<"` (exact equality) almost never fired, and constrained mode was almost
// never entered. The model generated natural spans like <<n * frac_1 * frac_2>>.
//
// Attempt 66 switched to `RenderedEndsWith(generated, "<<")` which fires EVERY TIME
// the model emits two `<` tokens in a row, forcing constrained mode on every intermediate
// span, creating 27.8 tiny 1-token spans per example → 0% accuracy.
//
// FIX: Pure unconstrained generation. Never enter constrained mode.
// The model writes natural <<expression>> spans. The evaluator extracts the LAST one.
// With stronger guidance telling the model to write ONE complete final formula inside
// << >> (not fragment variables), accuracy should substantially exceed attempt 1's 40.8%.
//
// Postconditions are trivially maintained: insideConstrainedOut and currentConstrainedOut
// never change (they remain valid by precondition), generated only grows, cost = steps ≤ maxSteps.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   The free-generation loop body never modifies insideConstrainedOut or
//   currentConstrainedOut. On entry, insideConstrainedOut == insideConstrained and
//   currentConstrainedOut == currentConstrained. If insideConstrained == false: the
//   implication is vacuously true throughout. If insideConstrained == true:
//   currentConstrainedOut stays equal to currentConstrained, and by method precondition
//   parser.IsValidPrefix(currentConstrained) holds; invariant preserved every iteration.
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: |generated| == |generatedPrefix| and steps == 0 → equality holds.
//   Loop step: UnconstrainedStep costs +1 so steps grows by 1. Then either EOS fires
//   (break without appending; |generated| unchanged) or generated grows by exactly 1
//   token. Both cases preserve |generated| <= |generatedPrefix| + steps.
//   Additionally, insideConstrainedOut ==> |currentConstrainedOut| <= |generated|:
//   currentConstrainedOut == currentConstrained satisfies |currentConstrained| <=
//   |generatedPrefix| by precondition, and |generated| >= |generatedPrefix| always
//   (generated is append-only), so this sub-invariant is preserved trivially.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve this math problem step by step. " +
  "At the very end of your response, write your final answer inside ONE pair of << >> delimiters. " +
  "The expression inside << >> MUST be the complete Python-evaluable formula using ALL relevant " +
  "variable names and arithmetic operators. " +
  "CORRECT: The answer is <<n * frac_1 * frac_2>>. " +
  "WRONG: The answer is <<n>> * frac_1 * frac_2. " +
  "Do NOT fragment the formula across multiple << >> spans. " +
  "Do NOT use << >> during reasoning steps — reserve << >> exclusively for the ONE final answer formula.");

var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
}

cost := steps;

